sources=[('Shared interval bounds', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/common_clickhouse.go', 320, 'The default source interval is start-inclusive and end-exclusive. The formatter at line 37 keeps whole seconds.'), ('All seven new evidence queries', '0d1b75da684ee0a9237020d6d500e117db6f7b4e', 'insights-server/internal/analyticsimpl/action_retrieve_conversation_assistance_usage_stats_clickhouse.go', 27, 'Only eligible agents are applied inside feature sources; eligible pairs are joined after feature reduction. No source timestamp bounds are supplied.'), ('Notes cluster switch', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/retrieve_note_taking_stats_clickhouse.go', 91, 'Metadata requests switch from Events to Conversations, including a different payload projection.'), ('Workflow cluster switch', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/retrieve_guided_workflow_stats_clickhouse.go', 82, 'Metadata requests switch from Events to Conversations.'), ('Summary exact timestamp join', '0d1b75da684ee0a9237020d6d500e117db6f7b4e', 'insights-server/internal/analyticsimpl/common_summarization_usage_clickhouse.go', 5, 'Generation and use must agree on conversation, agent and copied start time. This is preserved from main.'), ('GenAI aggregate joins', '0d1b75da684ee0a9237020d6d500e117db6f7b4e', 'insights-server/internal/analyticsimpl/retrieve_knowledge_assist_stats_clickhouse.go', 48, 'Usage joins message aggregates by requested grouping keys, including time buckets when requested.'), ('Population source and version selection', '0d1b75da684ee0a9237020d6d500e117db6f7b4e', 'insights-server/internal/analyticsimpl/common_conversation_population_clickhouse.go', 35, 'Both message and conversation copies receive exact bounds. Conversation time filtering occurs before latest-row selection at lines 79-94.'), ('Smart Compose hour matching', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/retrieve_smart_compose_stats_clickhouse.go', 38, 'Actual event time is filtered; attribution uses agent/hour instead of a conversation ID.'), ('Adherence metadata discarded', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/retrieve_adherences_clickhouse.go', 83, 'The reader discards parsed include/exclude metadata lists. Source timestamps still have bounds.'), ('Earlier messages can change start time', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'apiserver/internal/conversation/action_batch_upsert_conversation_messages.go', 1954, 'The inspected loop moves start time to an earlier message timestamp without a local maximum-delta guard.'), ('Events copy conversation start', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'shared/clickhouse/events/event.go', 540, 'ConversationStartTime comes from the supplied conversation, while CreateTime is ingestion wall clock.'), ('Conversations projection copies start', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'shared/clickhouse/conversations/conversation.go', 2505, 'Annotations and events copy conversation.StartedAt; their own creation time is a different column.'), ('Legacy combined API', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'insights-server/internal/analyticsimpl/retrieve_assistance_stats_clickhouse.go', 217, 'Message, moment and event scans receive time bounds; results are anchored on message aggregates.'), ('Conversation source sort key', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'shared/clickhouse/testing/schemas/ch_conv_schema.sql', 27, 'Base source tables are time-led. Do not assume every base table has monthly partitions; several by-conversation/metadata views do.'), ('Events source sort key', 'b6a2c65bdb6ba679a3bdf955b266cfd22f1a9ceb', 'shared/clickhouse/testing/schemas/ch_events_schema.sql', 18, 'Events source keys begin with copied conversation start time; analytics_event uses event_time instead.')]
