findings=[{'id': 'T1', 'title': 'Seven new evidence families scan historical data before eligibility intersection', 'classification': 'Confirmed scan behavior; production cost unknown', 'priority': 'Address in CONVI-7777 before broad rollout', 'trigger': 'One-day request, one eligible conversation/agent, months of feature history for the same agent.', 'trace': 'The evidence constructor supplies only an agent predicate. Feature rows are reduced to pairs before the ordinary join with assistance_usage_population. The final join excludes other conversations from the answer but cannot be assumed to prune all preceding work.', 'observed': 'A single-node synthetic MergeTree with 180,000 history rows returned the identical eligible pair with unbounded read_rows=180,002 and exact request bounds=2,050. Counts include the two tiny lookup tables.', 'impact': 'More history can increase source reads, pair reduction, memory and transfer even for a short request. This is demonstrated locally, not a measured production regression.', 'fix': 'Apply the requested [S,E) interval consistently to every physical evidence source, following the existing assistance APIs, and retain the final eligible-pair intersection. Audit copied timestamps and internal matching separately from source-scan alignment.', 'regression': 'Seed selected-agent history far outside the request, in-range evidence, out-of-cohort pairs and skewed copied timestamps. Assert exact results and inspect each physical read/remote plan; benchmark representative deployed data.'}, {'id': 'T2', 'title': 'Copied timestamps can disagree under the same requested interval', 'classification': 'Verified existing time-semantics difference; prevalence unknown', 'priority': 'Track separately from requested-range scan alignment', 'trigger': 'Conversation start changes after an evidence row copied the earlier value, or independent projections are refreshed at different times.', 'trace': 'Events and Conversations writers copy the conversation start field, independently of event creation/ingestion time. The upsert-message path can move StartedAt earlier based on a message timestamp. No maximum correction delta is enforced in that inspected loop.', 'observed': 'Synthetic evidence with copied start outside [S,E) is excluded by existing APIs but retained by the current new pair-based lookup when its cohort pair is supplied. Late arrival with an unchanged in-range copied start remains included in both.', 'impact': 'Late arrival and copied-time disagreement are different states. Applying the same request interval aligns source bounds but does not make independently copied timestamps agree. The current unbounded new lookup and existing bounded APIs can therefore return different evidence.', 'fix': 'Use the existing requested-range behavior as the scan baseline. Document and investigate timestamp-copy, correction and reindex behavior as a separate correctness question; no fixed-day expansion is proposed.', 'regression': 'Test copied timestamps before/inside/at the end of the request, unchanged copied time with late creation, and a conversation moved into/out of the request. Keep synthetic cases distinct from observed production data.'}, {'id': 'T3', 'title': 'Summary still loses use on an internal exact timestamp join', 'classification': 'Reproduced on main reader and PR reader; inherited behavior', 'priority': 'Resolve explicitly; a wider scan alone cannot fix it', 'trigger': 'Generation action at copied start October 1 00:00 and a qualifying copy at October 1 01:00, with the same conversation/agent. Both timestamps are inside the request.', 'trace': 'The feature joins valid generation to use USING (conversation_id, conversation_start_time, agent_user_id), before the new API can apply its pair intersection.', 'observed': 'Legacy used_summarization_count=0; new Summary evidence returns no pair. Generation count remains 1. Expanding source ranges cannot make unequal join keys equal.', 'impact': 'A conversation can lose Summary-use credit despite having both qualifying records. Aligning source bounds cannot resolve unequal internal join keys.', 'fix': 'Choose whether timestamp equality is an intended feature contract. If it is removed, preserve conversation/agent identity and decide whether generation-to-copy linkage needs a stronger annotation/session key. Keep any legacy behavior correction separate from a scan-only change.', 'regression': 'Same pair, differing copied times inside or outside the interval; unrelated generation/copy; wrong agent and duplicate generations.'}, {'id': 'T4', 'title': 'Time-bucket anchors can hide usage even when both source scans cover it', 'classification': 'Reproduced on main and PR legacy readers; new evidence lookup differs', 'priority': 'Cross-API parity decision and regression coverage', 'trigger': 'Two-day request. Conversation/message copy is October 1; usage annotation or generation/copy pair is October 2; no message/conversation aggregate exists for that agent on October 2.', 'trace': 'GenAI left-joins usage aggregates to message aggregates by agent/time bucket. Summary left-joins summary aggregates to conversation aggregates. Neither join proves conversation identity across those buckets.', 'observed': 'Legacy daily GenAI use is 0 and Summary use is 0, even with a two-day source interval that contains all rows. The new GenAI and Summary evidence queries return the eligible pair; new output buckets use population time. Notes/Workflow instead emit their event-copy day.', 'impact': 'Identical source scan ranges do not guarantee matching totals or trend placement. The legacy combined assistance API has the same message-bucket anchoring pattern.', 'fix': 'State whether the product groups adoption by population conversation start or feature-source copy. For conversation adoption, carry the pair plus chosen population time through aggregation; do not borrow legacy aggregate totals as the numerator.', 'regression': 'Same pair copied across midnight; UTC and non-UTC day/week boundaries; missing anchor bucket; include/exclude metadata; Agent and Team totals.'}, {'id': 'T5', 'title': 'Notes and Workflow depend on cluster choice and a second conversation copy', 'classification': 'Reproduced existing dependency and cross-API parity gap', 'priority': 'Include source coverage in CONVI-7777 validation', 'trigger': 'Conversations contains the eligible conversation and matching typed evidence. Events has the JSON usage event but lacks its conversation row; matching metadata is also available.', 'trace': 'Without metadata, legacy Notes/Workflow read Events and inner-join events to Events conversation_d by conversation ID. With metadata, legacy switches to Conversations. New Notes/Workflow always use the Events branch, even when the cohort was filtered with metadata in Conversations.', 'observed': 'Legacy no-metadata and new evidence queries return no Notes/Workflow usage. Adding a matching metadata filter causes both legacy endpoints to return 1 via Conversations.', 'impact': 'The same date range can cover different stored histories and return different usage merely because the selected source changes. Padding timestamps cannot restore a missing Events conversation row.', 'fix': 'Verify historical coverage, ingestion/retention/reindex behavior for both projections. Decide whether the new endpoint should require a second Events conversation record after cohort eligibility is already established. If removing that join, review source/agent/metadata gates explicitly.', 'regression': 'One cluster missing conversation or event; copied times disagree; matching metadata changes source; wrong-agent conversation rows; typed versus JSON payloads.'}, {'id': 'T6', 'title': 'The eligible population still filters copies before selecting the latest version', 'classification': 'Reproduced inherited population behavior; not a new evidence-query bug', 'priority': 'Track separately from source-scan optimization', 'trigger': 'An older conversation row starts October 1; a newer row for the same pair starts October 3; request is October 1. An in-range message copy remains.', 'trace': 'The population applies exact time bounds in the conversation source WHERE, then ORDER BY update_time DESC LIMIT 1 BY pair. The newer out-of-range row is removed before version selection. Message copies are also independently range-filtered.', 'observed': 'The population still returns the October 1 pair. A separate missing-message probe returns no population despite feature evidence.', 'impact': 'Calling this cohort globally current would overstate its contract. Widening only feature scans cannot recover a pair excluded by a stale message copy or correct an old version retained by prefiltering.', 'fix': 'Keep this separate from CONVI-7777 scan-only changes unless latest-state semantics are explicitly required. Define bounded candidate discovery versus global latest-state selection and preserve frozen ConversationStats behavior until reviewed.', 'regression': 'Newest version moves outside/inside the range; message and conversation disagree; same pair with multiple versions; new agent assignment; labels ON/OFF paths.'}, {'id': 'T7', 'title': 'Whole-second SQL formatting changes fractional request boundaries', 'classification': 'Reproduced shared boundary behavior', 'priority': 'Separate shared filter correction', 'trigger': 'Requested interval is [October 1 00:00:00.500, 00:00:01.500).', 'trace': 'The common timestampFormat is 2006-01-02 15:04:05. Both request endpoints are formatted without fractions before source conditions are built.', 'observed': 'A KB event at 00:00:00.250 is included although it precedes the request; one at 00:00:01.250 is excluded although it is inside. The query uses [00:00:00,00:00:01).', 'impact': 'Exact DateTime64 membership at API boundaries is not preserved. Normal whole-day UI requests do not trigger this specific case; direct fractional requests can.', 'fix': 'Use typed timestamp arguments or a format retaining required precision consistently across source and metadata filters. Do not fold this shared behavior correction into an unreviewed window change.', 'regression': 'Fractional lower/upper endpoints, zero-width ranges, microsecond-before/at end, and equivalent metadata-filter requests.'}, {'id': 'T8', 'title': 'Adjacent APIs have different attribution and filter contracts', 'classification': 'Smart Compose source-observed; adherence metadata gap reproduced', 'priority': 'Document exceptions and track separate corrections', 'trigger': 'A Smart Compose insert occurs in a later hour than conversation start, or an adherence request contains nonmatching metadata.', 'trace': 'Smart Compose filters analytics_event.event_time and joins to agent/hour of conversation starts. RetrieveAdherences discards the parsed metadata inclusion/exclusion lists.', 'observed': 'All inspected scans remain time-bounded. Smart Compose attribution cannot be equated to conversation-level membership from these joins. The adherence fixture survives a nonmatching metadata filter with the same response as no filter.', 'impact': 'A uniform historical scan range cannot make event-time metrics, conversation-start metrics and metadata semantics equivalent. Silence/Hold or P2 features need explicit contracts before admission into the new union.', 'fix': 'Keep Smart Compose and email additions outside V1 as scoped. When revisiting them, require conversation-linked actual-use evidence and explicit filters. Define whether adherence metadata should be honored or rejected, then address that API separately.', 'regression': 'Long conversation with later-hour insert; another conversation in that hour; same text twice; nonmatching metadata for adherence; missing delivered-action linkage.'}]
steps=[{'title': 'Existing feature APIs', 'status': 'Observed baseline on pinned main', 'problem': 'Bound scan cost using the requested interval, but apply that interval independently to each copied source timestamp.', 'why': 'Feature APIs build their own source predicates and aggregate at different grains.', 'change': 'Every inspected source read receives exact bounds. Some feature joins require timestamp equality or anchor on an aggregate bucket.', 'remaining': 'Copied timestamps, source coverage and aggregation can disagree even when the SQL bounds match.', 'code': "for each physical feature source:\n    WHERE copied_conversation_start >= S\n      AND copied_conversation_start < E\naggregate using that feature's existing joins/buckets", 'diff': 'Baseline: independently bounded feature-source scans.'}, {'title': 'New API in PR #33993', 'status': 'Observed implementation at 0d1b75da68', 'problem': 'Count distinct eligible conversation/agent pairs with any qualifying assistance use.', 'why': 'Legacy totals count events, actions or sessions and do not provide one shared adoption population.', 'change': 'Resolve the filtered population; scan selected-agent feature history; reduce and intersect pairs; use population time for buckets.', 'remaining': 'Historical work is unbounded. Summary internal timestamp equality, Events copy dependencies and population limitations remain.', 'code': 'population = existingConversationEligibility(S, E, filters)\nfor feature in sevenFamilies:\n    pairs = DISTINCT featureRows(agent IN population.agents)\n    used += pairs JOIN population ON (conversation_id, agent_user_id)\naggregate(used, bucketTime=population.conversation_time)', 'diff': '- exact source bounds in feature predicates\n+ eligible-agent source filter\n+ shared pair intersection after source reduction\n+ population time for adoption buckets'}, {'title': 'Align scans with existing APIs', 'status': 'User-directed baseline; implementation pending', 'problem': 'Bound source history consistently with the other assistance APIs for the same requested time range.', 'why': 'Existing feature APIs apply [S,E) to their source clocks; the seven new evidence families currently omit those bounds.', 'change': 'Pass the requested start and end to every participating physical evidence source and retain exact population eligibility plus the final conversation/agent intersection.', 'remaining': 'Copied-time disagreement, Summary linkage, cluster-copy coverage and bucket attribution remain separate correctness questions. Production performance remains unmeasured.', 'code': 'eligibility = existingPopulation(S, E, filters)\nfor physicalSource in featureSources:\n    rows = read(source, startInclusive=S, endExclusive=E,\n                agents=eligibility.agents)\nused = featurePredicate(rows) JOIN eligibility ON pair\n# Match existing API source bounds; review timestamp-copy issues separately.', 'diff': '+ requested [S,E) bounds on every participating evidence source\n= exact population eligibility and final pair intersection\n? timestamp-copy, source-coverage and join corrections tracked separately'}]
