matrix='<table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in ['Feature / API','Sources and clock','Existing scan','New API','Parity caveat'])+'</tr></thead><tbody>'+''.join('<tr><th>'+esc(r[0])+'<small>'+esc(r[1])+'</small></th><td>'+esc(r[2])+'<small>'+esc(r[3])+'</small></td><td>'+esc(r[4])+'</td><td>'+esc(r[5])+'</td><td>'+esc(r[6])+'</td></tr>' for r in features)+'</tbody></table>'
cards=''.join('<article class="finding" id="'+f['id']+'"><p class="tag">'+esc(f['id']+' · '+f['classification'])+'</p><h3>'+esc(f['title'])+'</h3>'+''.join('<p><b>'+esc(label)+': </b>'+esc(f[key])+'</p>' for label,key in [('Trigger','trigger'),('Trace','trace'),('Observed','observed'),('Impact / limit','impact'),('Fix boundary','fix'),('Regression','regression')])+'</article>' for f in findings)
sourcehtml='<ol>'+''.join('<li><a href="'+link(s)+'">'+esc(s[0])+'</a> — '+esc(s[4])+'</li>' for s in sources)+'</ol>'
acceptance=md[md.index('## Implementation boundary and acceptance criteria')+2:md.index('## Known related issues')-1]
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CONVI-7777 · Assistance scan audit</title><style>
:root{{--ink:#1e293b;--muted:#526277;--line:#d8e0e9;--blue:#185abd;--soft:#eef5ff}}*{{box-sizing:border-box}}body{{font:16px/1.62 system-ui,sans-serif;color:var(--ink);background:#f5f7fa;margin:0}}main{{max-width:1250px;margin:auto;padding:35px 32px 80px}}h1{{font-size:clamp(28px,4vw,43px);line-height:1.15;margin:10px 0 20px}}h2{{font-size:26px;margin-top:46px}}h3{{line-height:1.3}}p{{max-width:100ch}}a{{color:var(--blue)}}small{{display:block;color:var(--muted);font-size:13px}}.tag{{font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}}.lead{{font-size:19px}}.panel,.finding{{background:white;border:1px solid var(--line);border-radius:14px;padding:24px;margin:18px 0}}.finding{{border-left:5px solid #d99a27}}.flow{{display:flex;gap:12px;align-items:stretch;flex-wrap:wrap}}.flow div{{flex:1;min-width:160px;padding:16px;background:var(--soft);border-radius:8px}}.flow span{{align-self:center}}.metrics{{display:flex;gap:14px;flex-wrap:wrap}}.metrics p{{flex:1;min-width:180px;background:white;border:1px solid var(--line);border-radius:12px;padding:18px}}.metrics strong{{display:block;font-size:28px}}table{{border-collapse:collapse;width:100%;background:white;font-size:14px}}th,td{{border:1px solid var(--line);text-align:left;vertical-align:top;padding:13px}}th{{background:#eff3f8}}.table-wrap{{overflow:auto}}button,select{{font:inherit;border:1px solid #a8b9cc;background:white;border-radius:7px;padding:8px 12px;cursor:pointer}}button[aria-pressed=true]{{background:var(--blue);color:white}}button:disabled{{opacity:.4;cursor:default}}.controls{{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#152238;color:#e5edf9;border-radius:9px;padding:20px;font:14px/1.6 ui-monospace,monospace}}#step-title{{font-size:23px}}#probe-result{{min-height:130px;max-height:500px;overflow:auto}}label{{font-weight:600}}.recommendation{{background:#e9f3ee;border:1px solid #a8cbb5;padding:24px;border-radius:12px}}@media(max-width:650px){{main{{padding:22px 14px}}.panel,.finding{{padding:17px}}th,td{{min-width:160px}}.flow span{{display:none}}}}@media print{{button,select,.controls{{display:none}}body{{background:white}}main{{max-width:none}}.finding{{break-inside:avoid}}}}
</style></head><body><main>
<aside class="panel"><strong>Local implementation follow-up:</strong> Requested-range bounds and the Notes/Workflow conditional source/payload switch are implemented locally and pass focused Go/Bazel verification. Findings below retain the pinned pre-change evidence. <a href="convi-7777-time-source-parity-follow-up.md">Follow-up and concrete examples</a>. No push or deployment.</aside>
<p class="tag">CONVI-7777 · read-only investigation · October 21, 2026</p><h1>Same date range.<br>Different scans, evidence and buckets.</h1><p class="lead">{esc(intro)}</p><p><a href="https://github.com/cresta/go-servers/pull/33993#discussion_r4340956097">Original review comment</a> · Main <code>{main[:10]}</code> · PR <code>{head[:10]}</code></p>
<div class="metrics"><p><strong>10</strong>existing APIs inspected<small>Both Hint paths; shared population also traced</small></p><p><strong>83</strong>generated SQL variants<small>Per reader configuration; source and metadata paths</small></p><p><strong>381 / 107</strong>SQL executions / passed assertions<small>Zero SQL errors in the final synthetic run</small></p></div>
<h2>Contract and workflow</h2><p>{esc(contract)}</p><div class="flow"><div><b>Request [S,E)</b><small>ACL, users, attributes, metadata</small></div><span>→</span><div><b>Eligible pairs</b><small>Existing conversation/message population</small></div><span>→</span><div><b>Feature evidence</b><small>Source clock, scan bounds, feature joins</small></div><span>→</span><div><b>Counts and buckets</b><small>Intersect pairs, union features, use population time</small></div></div>
<h2>Cross-API scan matrix</h2><p>“Exact [S,E)” describes SQL predicates on each source’s own clock. It does not guarantee equal stored history, newest-state selection or final membership.</p><div class="table-wrap">{matrix}</div>
<h2>How the design differs</h2><p>These are explanatory snapshots. The last step reflects the user-directed scan baseline; it is not implemented.</p><section class="panel"><div class="controls" id="step-buttons"></div><p class="tag" id="step-status"></p><h3 id="step-title"></h3><div id="step-explanation"></div><div class="controls"><button id="snapshot" aria-pressed="true">Code snapshot</button><button id="changes" aria-pressed="false">Change from previous</button></div><pre id="step-code"></pre><div class="controls"><button id="previous">Previous</button><button id="next">Next</button></div><p id="step-count" aria-live="polite"></p></section>
<h2>Local scan-pruning evidence</h2><p>The same eligible pair is returned in every row below. This is one synthetic 180,000-row single-node MergeTree experiment on ClickHouse 24.2.3.70; it demonstrates source pruning, not customer latency or distributed network volume. The two small lookup rows are included in read_rows.</p><div class="table-wrap"><table><thead><tr><th>Variant</th><th>Read rows</th><th>Result</th></tr></thead><tbody>'''+''.join('<tr><td>'+esc(v['variant'])+'</td><td>'+str(v['local_metrics'][0]['read_rows'])+'</td><td>Same one conversation/agent pair</td></tr>' for v in pruning['records'])+f'''</tbody></table></div>
<h2>Findings and worked scenarios</h2><p>These are demonstrated mechanisms and conditional results. Customer prevalence and production performance remain unmeasured. Existing semantics are separated from the new endpoint’s scan issue.</p>{cards}
<h2>Inspect the captured SQL results</h2><p>Direct SQL probes isolate query semantics. New evidence probes use a manually supplied eligible-pair table; they are not full RPC calls. Population probes execute the actual population query separately. An empty evidence result does not necessarily make the combined metric zero if another feature qualifies.</p><section class="panel"><div class="controls"><label>Scenario <select id="scenario" aria-label="Scenario"></select></label><label>Feature <select id="feature" aria-label="Feature"></select></label></div><p id="probe-count" aria-live="polite"></p><pre id="probe-result"></pre></section>
<h2>What CONVI-7777 should validate</h2><ol>'''+''.join('<li>'+esc(p[3:] if p[:2].strip('.').isdigit() else p)+'</li>' for p in acceptance if p)+f'''</ol>
<h2>Effects beyond the diff</h2><p>The same request reaches two independently populated clusters, different copied clocks, metadata materialized views and multiple feature-internal joins. The new endpoint cannot repair evidence already removed by its message-anchored population. Main and PR GenAI/Summary readers were compiled separately and their focused results agree. Other inspected legacy source readers are identical at these revisions.</p><p>Known related issues remain in the <a href="convi-7777-assistance-analytics-issue-register.md">existing issue register</a>: metadata exclusions under non-nullable joins, Summary payload semantics, Notes metadata projection enums, attribution and denominator contracts. The Notes metadata fixture deliberately supplies the query’s expected type 5 to isolate source dependency; it does not prove production enum parity.</p>
<h2>Non-blocking maintainability</h2><p>Use separate names for exact eligibility and evidence scan bounds. Centralize an adopted policy and document source clocks and cluster switches. These suggestions do not replace the semantic decisions or measurements.</p>
<h2>Recommendation</h2><div class="recommendation"><b>Use the requested [S,E) interval, matching existing assistance APIs.</b><p>Apply those bounds to every participating evidence source, preserve exact eligibility, and validate physical scans plus feature-internal joins. Resolve inherited correctness differences as explicit follow-ups. The current new API is cohort-filtered but has no bounded evidence-scan contract; existing APIs are bounded but are not semantically interchangeable.</p></div>
<h2>Verification and limits</h2><p>Final synthetic run: 381 SQL executions, zero SQL errors, 107 explicit assertions. Two Go query-generation configurations pass. Source snapshots and evidence are pinned. No product code, PR content or external ticket was changed. Production deployment, customer frequency, retention equality, cold/warm latency and distributed-transfer cost were not verified.</p><p>Only synthetic local databases were used and removed. No AWS, Okta, Azure or SSH credential/profile was selected or read. GitHub reads used existing gh/git authentication. <span id="qa-note">Original report browser controls passed. Revised requested-range report passes static HTML/JavaScript, displayed-variant and companion-link checks. Visual recheck was blocked by the browser file-URL policy. See report-qa.json in the evidence directory.</span></p>
<h2>Pinned sources</h2>{sourcehtml}<p>Companion: <a href="convi-7777-assistance-scan-audit.md">Markdown investigation</a>. Reproduction scripts and raw results are saved under the analytics session evidence directory.</p>
</main><script>
const steps='''+json.dumps(steps).replace('<','\\u003c')+''';
const records='''+json.dumps(records).replace('<','\\u003c')+''';
let currentStep=0,showChanges=false;
function renderStep(){const step=steps[currentStep];document.getElementById('step-status').textContent=step.status;document.getElementById('step-title').textContent=step.title;const panel=document.getElementById('step-explanation');panel.replaceChildren();for(const [label,key] of [['Problem this step addresses','problem'],['Why the problem exists','why'],['What this step changes','change'],['What remains unresolved','remaining']]){const paragraph=document.createElement('p');const bold=document.createElement('b');bold.textContent=label+': ';paragraph.append(bold,document.createTextNode(step[key]));panel.append(paragraph);}document.getElementById('step-code').textContent=showChanges?step.diff:step.code;document.getElementById('previous').disabled=currentStep===0;document.getElementById('next').disabled=currentStep===steps.length-1;document.getElementById('step-count').textContent=`Step ${currentStep+1} of ${steps.length}`;document.getElementById('snapshot').setAttribute('aria-pressed',String(!showChanges));document.getElementById('changes').setAttribute('aria-pressed',String(showChanges));for(const [i,button] of [...document.getElementById('step-buttons').children].entries())button.setAttribute('aria-pressed',String(i===currentStep));}
for(const [i,step] of steps.entries()){const button=document.createElement('button');button.textContent=step.title;button.addEventListener('click',()=>{currentStep=i;renderStep();});document.getElementById('step-buttons').append(button);}
document.getElementById('previous').addEventListener('click',()=>{if(currentStep>0)currentStep--;renderStep();});document.getElementById('next').addEventListener('click',()=>{if(currentStep<steps.length-1)currentStep++;renderStep();});document.getElementById('snapshot').addEventListener('click',()=>{showChanges=false;renderStep();});document.getElementById('changes').addEventListener('click',()=>{showChanges=true;renderStep();});
function options(id,values){const element=document.getElementById(id);for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;element.append(option);}}
options('scenario',[...new Set(records.map(r=>r.scenario))]);options('feature',['All features',...[...new Set(records.map(r=>r.feature))].sort()]);
function renderProbes(){const scenario=document.getElementById('scenario').value;const feature=document.getElementById('feature').value;const filtered=records.filter(r=>r.scenario===scenario&&(feature==='All features'||r.feature===feature));document.getElementById('probe-count').textContent=`${filtered.length} captured query results`;document.getElementById('probe-result').textContent=JSON.stringify(filtered,null,2);}
for(const id of ['scenario','feature'])document.getElementById(id).addEventListener('change',renderProbes);renderStep();renderProbes();
</script></body></html>'''
(out/'convi-7777-assistance-scan-audit.html').write_text(body)
print(out/'convi-7777-assistance-scan-audit.html')
